public MimeFilteringDecorator(Parser parser, Set<MediaType> includeTypes, Set<MediaType> excludeTypes) {
    super(parser);
    this.includeTypes = includeTypes != null ? Collections.unmodifiableSet(new HashSet<>(includeTypes)) : Collections.emptySet();
    this.excludeTypes = excludeTypes != null ? Collections.unmodifiableSet(new HashSet<>(excludeTypes)) : Collections.emptySet();
}
